// Probe the MCP server for any info endpoints
const probes = [];
for (const path of ["/", "/health", "/info", "/version", "/mcp"]) {
  try {
    const res = await fetch("http://172.21.0.2:8181" + path, { method: "GET" });
    const text = await res.text();
    probes.push({ path, status: res.status, body: text.slice(0, 500) });
  } catch (e) {
    probes.push({ path, error: String(e) });
  }
}
return probes;

