// Fully inlined DSL (no !include, no !docs) — does the MCP server parse it?
const dsl = `workspace "Order Service" "Multi-file Structurizr workspace assembled with !include, documented with !docs" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses the catalogue and places orders through the web application"
        supportAgent = person "Support Agent" "A support team member who looks up and amends orders on behalf of customers"

        orderService = softwareSystem "Order Service" "Accepts, stores and processes customer orders" {
            webApp = container "Web Application" "Server-rendered UI for browsing the catalogue and placing orders" "TypeScript/React" "Web"
            api = container "Order API" "REST API that validates, persists and prices orders" "Java/Spring Boot" "Service"
            database = container "Order Database" "System of record for orders and order items" "PostgreSQL 16" "Database"
            queue = container "Message Queue" "Buffers order events for asynchronous processing" "RabbitMQ" "Queue"
            worker = container "Order Worker" "Consumes order events and updates order status" "Java/Spring Boot" "Worker"
        }

        paymentGateway = softwareSystem "Payment Gateway" "Third-party service that authorizes and captures card payments" "External"

        customer -> orderService.webApp "places orders through" "HTTPS"
        supportAgent -> orderService.webApp "looks up and amends orders through" "HTTPS"
        orderService.webApp -> orderService.api "calls" "HTTPS/JSON"
        orderService.api -> orderService.database "reads from and writes to" "JDBC/SQL"
        orderService.api -> orderService.queue "publishes order events to" "AMQP" "Async"
        orderService.worker -> orderService.queue "consumes order events from" "AMQP" "Async"
        orderService.worker -> orderService.database "updates order status in" "JDBC/SQL"
        orderService.api -> paymentGateway "authorizes and captures payments via" "HTTPS/JSON"
    }

    views {
        systemLandscape "Landscape" "All people and systems in scope" {
            include *
            autoLayout
            title "System Landscape"
        }

        systemContext orderService "Context" "Order Service and its direct neighbours" {
            include *
            autoLayout
            title "System Context for Order Service"
        }

        container orderService "Containers" "Containers that make up the Order Service" {
            include *
            autoLayout
            title "Containers for Order Service"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
            element "Worker" {
                shape Robot
            }
            relationship "Relationship" {
                routing Orthogonal
            }
            relationship "Async" {
                style dashed
            }
        }
    }
}`;
const result = await tools.structurizr.parse({ dsl });
return result;

