{"command": "which awk; awk 'BEGIN{print "awk works"}'
cat > /tmp/assemble.awk <<'AWK'
function dir_of(path,    i) {
  i = length(path)
  while (i > 0 && substr(path, i, 1) != "/") i--
  if (i <= 1) return "/"
  return substr(path, 1, i - 1)
}
function assemble(file, dir,    line, trimmed, inc, full, cmd, f) {
  while ((getline line < file) > 0) {
    trimmed = line
    sub(/^[ \t]+/, "", trimmed)
    if (trimmed ~ /^!include[ \t]/) {
      inc = trimmed
      sub(/^!include[ \t]+/, "", inc)
      sub(/[ \t]+$/, "", inc)
      full = dir "/" inc
      if (system("test -d '" full "'") == 0) {
        cmd = "ls '" full "'/*.dsl 2>/dev/null"
        while ((cmd | getline f) > 0) {
          assemble(f, dir_of(f))
        }
        close(cmd)
      } else if (system("test -f '" full "'") == 0) {
        assemble(full, dir_of(full))
      } else {
        print "ERROR: !include target not found: " full > "/dev/stderr"
        exit 1
      }
    } else {
      print line
    }
  }
  close(file)
}
BEGIN {
  root = ARGV[1]
  assemble(root, dir_of(root))
}
AWK
echo "=== case B (subdir) ==="
