{"code": "const b64 = "";
const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
const dsl = new TextDecoder().decode(bytes);

const out = {};
for (const [name, fn] of [
  ["parse", tools.structurizr.parse],
  ["validate", tools.structurizr.validate],
  ["inspect", tools.structurizr.inspect],
]) {
  try {
    out[name] = await fn({ dsl });
  } catch (e) {
    out[name] = { error: String(e) };
  }
}
if (out.parse && !out.parse.error) {
  const p = out.parse;
  out.parse_summary = {
    name: p.name,
    scope: p.configuration && p.configuration.scope,
    people: p.model.people.map(x => x.name),
    systems: p.model.softwareSystems.map(x => x.name + (x.containers ? " [" + x.containers.length + " containers]" : "")),
    views: {
      landscape: (p.views.systemLandscapeViews||[]).map(v=>v.key),
      context: (p.views.systemContextViews||[]).map(v=>v.key),
      container: (p.views.containerViews||[]).map(v=>v.key),
    },
    styleElements: p.views.configuration.styles.elements.length,
    styleRelationships: p.views.configuration.styles.relationships.length,
  };
  delete out.parse;
}
return out;"}
